/**
 * Generates packages/core/src/bibleBreaksData.ts: for each verse where at
 * least one of OpenBible.info's 20 English Bibles starts a section, how many
 * do (library/divisions/openbible-section-counts.tsv, CC BY 4.0). Dividing a
 * book your own way shows them in the text (docs/breaking-up-the-bible.md).
 *
 *   npx tsx scripts/bible-breaks.ts
 *
 * Re-run when the counts file changes and commit the generated file.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { OSIS } from './library-seed';

const tsv = readFileSync(fileURLToPath(new URL('../library/divisions/openbible-section-counts.tsv', import.meta.url)), 'utf8');
const byBook = new Map<string, Map<string, number>>();
for (const line of tsv.split('\n')) {
  if (!line || line.startsWith('#')) continue;
  const [start, , , n] = line.split('\t');
  const [osis, c, v] = start!.split('.');
  const book = OSIS[osis!];
  if (!book) throw new Error(`unknown OpenBible book ${osis}`);
  const at = `${Number(c)}:${Number(v)}`;
  const counts = byBook.get(book) ?? new Map<string, number>();
  counts.set(at, (counts.get(at) ?? 0) + Number(n));
  byBook.set(book, counts);
}
const order = (k: string) => k.split(':').map(Number) as [number, number];
const books: Record<string, string> = {};
for (const [book, counts] of byBook) {
  books[book] = [...counts].sort(([a], [b]) => { const [ac, av] = order(a); const [bc, bv] = order(b); return ac - bc || av - bv; })
    .map(([k, n]) => `${k}=${n}`).join(' ');
}
writeFileSync(fileURLToPath(new URL('../packages/core/src/bibleBreaksData.ts', import.meta.url)),
  `// Generated by scripts/bible-breaks.ts from OpenBible.info's section counts (CC BY 4.0). Do not edit.\n/* eslint-disable */\n` +
  `/** Per book (USFM), "chapter:verse=bibles" for each verse where that many of 20 English Bibles start a section. */\n` +
  `export const BIBLE_BREAKS: Record<string, string> = ${JSON.stringify(books)};\n`);
console.log(Object.keys(books).length, 'books');
